import{_ as i,C as r,o as n,c as h,j as d,a as e,E as o,ah as l}from"./chunks/framework.BpF7DVZ1.js";const P=JSON.parse('{"title":"日志","description":"","frontmatter":{},"headers":[],"relativePath":"components/log.md","filePath":"components/log.md","lastUpdated":1788635489000}'),s={name:"components/log.md"},g={id:"日志",tabindex:"-1"};function b(u,t,p,x,m,f){const c=r("Badge"),a=r("XhDemo");return n(),h("div",null,[d("h1",g,[t[0]||(t[0]=e("日志 ",-1)),o(c,{type:"info",text:"log"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#日志","aria-label":'Permalink to "日志 <Badge type="info" text="log" />"'},"​",-1))]),t[3]||(t[3]=l('<p>一块等宽排版的滚动区域，一行一条，可以自动跟到底部。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>构建输出、运行日志、命令行回显。</li><li>任意会从底部往下长、希望一直跟到底的内容：内容不必分得出「第几条、谁说的」， 一整段往里追加就行。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>内容是一段会话，条目有身份、要能逐条遍历：用<a href="./message-feed">消息流</a>。</li><li>展示的是结构化记录、需要筛选排序：用<a href="./table">表格</a>。</li><li>是一段代码：用<a href="./code-view">代码视图</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>骨架四层：<code>root</code> · <code>viewport</code> · <code>content</code> · <code>line</code>；一行写什么由作者定，组件只给身份与等宽排版。 另有两个可缺省的部件：<code>scroll-to-end-trigger</code> 与 <code>live-region</code>。</li><li><code>rows</code> 按行数定高。</li><li>自动跟到底部；用户往上翻时停住跟随，回到底部再恢复。</li><li>内置「回到底部」：离底时冒出来，按下去归位并重新粘附。留空时皮肤画一枚向下的字形， 往按钮里塞节点即换成自己的图形。</li><li>视口自身可聚焦，整块日志占一个 Tab 停靠位，方向键与翻页键交给浏览器滚动。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>root / viewport / content / line 四层；一行写什么由作者定，组件只给身份与等宽排版</p>',10)),o(a,{src:"log/01-basic"}),t[4]||(t[4]=d("h3",{id:"按行数定高",tabindex:"-1"},[e("按行数定高 "),d("a",{class:"header-anchor",href:"#按行数定高","aria-label":'Permalink to "按行数定高"'},"​")],-1)),t[5]||(t[5]=d("p",null,"rows 定的是「看得见几行」，一行有多高归皮肤，改 --xh-log-line-height 两边一起变",-1)),o(a,{src:"log/02-rows"}),t[6]||(t[6]=d("h3",{id:"自动跟到底部",tabindex:"-1"},[e("自动跟到底部 "),d("a",{class:"header-anchor",href:"#自动跟到底部","aria-label":'Permalink to "自动跟到底部"'},"​")],-1)),t[7]||(t[7]=d("p",null,"新行进来时视口自己跟着走；往上滚一段就停住跟随，组件报出的 atBottom 与 scrollToBottom 够自己画一条回到最新",-1)),o(a,{src:"log/03-follow"}),t[8]||(t[8]=d("h3",{id:"取行中",tabindex:"-1"},[e("取行中 "),d("a",{class:"header-anchor",href:"#取行中","aria-label":'Permalink to "取行中"'},"​")],-1)),t[9]||(t[9]=d("p",null,"loading 让日志区报 aria-busy 并把指针换成忙碌态；「正在拉取」那一行是作者自己渲的",-1)),o(a,{src:"log/04-loading"}),t[10]||(t[10]=d("h3",{id:"级别",tabindex:"-1"},[e("级别 "),d("a",{class:"header-anchor",href:"#级别","aria-label":'Permalink to "级别"'},"​")],-1)),t[11]||(t[11]=d("p",null,"行上写 level，四档 debug / info / warn / error 由皮肤染色；时间戳与行内标记仍归作者",-1)),o(a,{src:"log/05-levels"}),t[12]||(t[12]=d("h3",{id:"换成自绘滚动条",tabindex:"-1"},[e("换成自绘滚动条 "),d("a",{class:"header-anchor",href:"#换成自绘滚动条","aria-label":'Permalink to "换成自绘滚动条"'},"​")],-1)),t[13]||(t[13]=d("p",null,"视口给个 id，用滚动条的 controls 挂上去；条子浮在内容之上，不占宽度也不留空道",-1)),o(a,{src:"log/06-scrollbar"}),t[14]||(t[14]=d("h3",{id:"回到底部与播报",tabindex:"-1"},[e("回到底部与播报 "),d("a",{class:"header-anchor",href:"#回到底部与播报","aria-label":'Permalink to "回到底部与播报"'},"​")],-1)),t[15]||(t[15]=d("p",null,"往上翻一段，右下角那颗钮自己冒出来，按下去归位并重新粘附；输出跑完在播报区念一句结论",-1)),o(a,{src:"log/07-scroll-button"}),t[16]||(t[16]=l('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-log&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhLogContent</code> <code>XhLogLine</code> <code>XhLogLiveRegion</code> <code>XhLogRoot</code> <code>XhLogScrollToEndTrigger</code> <code>XhLogViewport</code></td></tr><tr><td>组合式函数</td><td><code>useLog</code></td></tr><tr><td>状态机</td><td><code>logMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/log.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;log&quot;</code>：<strong><code>root</code></strong> · <strong><code>viewport</code></strong> · <strong><code>content</code></strong> · <code>line</code> · <code>scroll-to-end-trigger</code> · <code>live-region</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>threshold</code></td><td><code>number</code></td><td></td><td>距底多少 px 视为在底，缺省用粘底原语的默认值。</td></tr><tr><td><code>onStickChange</code></td><td><code>(details: LogStickChangeDetails) =&gt; void</code></td><td></td><td>粘底状态变化时通知宿主。</td></tr><tr><td><code>loading</code></td><td><code>boolean</code></td><td></td><td>行还在路上：日志区报 aria-busy，根落 data-loading。</td></tr><tr><td><code>rows</code></td><td><code>number</code></td><td></td><td>视口按多少行定高；缺省时高度由皮肤给。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。改的是行文字号与内衬，行高不随档变。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;LogTranslations&gt;</code></td><td></td><td></td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>stick-change</code></td><td><code>LogStickChangeDetails</code></td><td>粘底状态变化；detail 为 <code>{ atBottom: boolean, sticking: boolean }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhLogRoot</code></td><td><code>default</code></td><td><code>LogRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>scroll-to-end-trigger</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code></p><p><strong>事件</strong>：<code>STICK.CHANGE</code> · <code>SCROLL_TO_BOTTOM</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useLog</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>rows</code></td><td><code>number | undefined</code></td><td>取整后的行数；rows 缺席或不是正数时为 undefined。</td></tr><tr><td><code>loading</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>atBottom</code></td><td><code>boolean</code></td><td>当前滚动位置是否落在底部阈值内。</td></tr><tr><td><code>sticking</code></td><td><code>boolean</code></td><td>新行进来时是否自动跟到底。</td></tr><tr><td><code>showScrollToEndTrigger</code></td><td><code>boolean</code></td><td>是否显示回到底部按钮，不在底部时为 true。</td></tr><tr><td><code>scrollToBottom</code></td><td><code>() =&gt; void</code></td><td>滚到底部并恢复粘附。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getViewportProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLineProps</code></td><td><code>(props?: LogLineProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getScrollToEndTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getLiveRegionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/practices/structural-roles/" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code></td><td>焦点进入日志区</td><td>日志区自身可聚焦，方向键/PageUp/PageDown/Home/End 交给浏览器滚动，组件不接管</td></tr><tr><td><code>Space</code> / <code>Enter</code></td><td>焦点在&quot;回到底部&quot;按钮上</td><td>滚回底部并重新粘附</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>viewport</code></td><td><code>aria-busy</code></td><td>&#39;true&#39; | undefined</td></tr><tr><td><code>viewport</code></td><td><code>aria-label</code></td><td>label.log</td></tr><tr><td><code>viewport</code></td><td><code>aria-live</code></td><td>&#39;off&#39;</td></tr><tr><td><code>viewport</code></td><td><code>role</code></td><td>&#39;log&#39;</td></tr><tr><td><code>scroll-to-end-trigger</code></td><td><code>aria-label</code></td><td>label.scrollToBottom</td></tr><tr><td><code>live-region</code></td><td><code>aria-atomic</code></td><td>&#39;true&#39;</td></tr><tr><td><code>live-region</code></td><td><code>aria-live</code></td><td>&#39;polite&#39;</td></tr><tr><td><code>live-region</code></td><td><code>role</code></td><td>&#39;status&#39;</td></tr></tbody></table><ul><li>视口是 <code>role=log</code>，但它隐含的 <code>aria-live</code> 被显式关掉：一行来一句地念，连成串的输出 就成了读屏里的噪声。</li><li>播报走独立的 <code>live-region</code>：宿主决定念哪一句、什么时候念，例如一段输出跑完之后念结论 与错误条数。别把每一行原样写进去，那就等于把关掉的逐行播报又打开了一遍。</li><li>成批取行期间视口报 <code>aria-busy</code>；播报区是视口的兄弟节点，不受它压制。</li></ul><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/log.css</code> 按部件选择：<code>[data-scope=&quot;log&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 与 <code>xihan.motion</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-at-bottom</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-loading</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-sticking</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>line</code></td><td><code>data-level</code></td><td>line?.level</td></tr><tr><td><code>scroll-to-end-trigger</code></td><td><code>data-state</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-log-bg</code> · <code>--xh-log-border</code> · <code>--xh-log-content-px</code> · <code>--xh-log-fg</code> · <code>--xh-log-font</code> · <code>--xh-log-font-size</code> · <code>--xh-log-icon-size</code> · <code>--xh-log-level-debug-fg</code> · <code>--xh-log-level-error-fg</code> · <code>--xh-log-level-info-fg</code> · <code>--xh-log-level-warn-fg</code> · <code>--xh-log-line-height</code> · <code>--xh-log-radius</code> · <code>--xh-log-rows</code> · <code>--xh-log-scroll-to-end-trigger-bg</code> · <code>--xh-log-scroll-to-end-trigger-bg-hover</code> · <code>--xh-log-scroll-to-end-trigger-border</code> · <code>--xh-log-scroll-to-end-trigger-fg</code> · <code>--xh-log-scroll-to-end-trigger-inset</code> · <code>--xh-log-scroll-to-end-trigger-radius</code> · <code>--xh-log-scroll-to-end-trigger-shadow</code> · <code>--xh-log-scroll-to-end-trigger-size</code> · <code>--xh-log-tab-size</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>关键帧 <code>xh-log-button-in</code> 随皮肤自带，不引用别处文件里的名字；<code>background</code> · <code>scale</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>行内可以用<a href="./highlight">文本高亮</a>标出关键词。</li><li>给视口一个 id，把<a href="./scrollbar">滚动条</a>的 <code>controls</code> 指过去，条子与视口平级摆在 <code>root</code> 里：它浮在内容之上，不占宽度。没挂自绘滚动条时视口自己留一条空道，原生滚动条出现与消失不会推动文字。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>用户往上翻时不要强行拉回底部，那是最恼人的行为之一。</li><li>行数很大时截断或虚拟化，别把十万行全挂上去。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>每来一行就整块重渲。</li><li>不给复制或下载全部日志的入口。</li><li>把每一行都写进播报区：读屏会被逐行打断，什么也听不清。</li></ul>',48))])}const k=i(s,[["render",b]]);export{P as __pageData,k as default};
